14	export function nextGeneration(livingCells: Cell[]): Cell[] {
15	  const aliveKeys = new Set(livingCells.map(toKey));
16	  const neighborCounts = countNeighbors(livingCells);
17	
18	  return [...neighborCounts.values()]
19	    .filter(({ cell, count }) => isAliveNextGeneration(count, aliveKeys.has(toKey(cell))))
20	    .map(({ cell }) => cell);
21	}
