23	type NeighborEntry = { cell: Cell; count: number };
24	
25	function countNeighbors(livingCells: Cell[]): Map<string, NeighborEntry> {
26	  const counts = new Map<string, NeighborEntry>();
27	  for (const [x, y] of livingCells) {
28	    for (const [dx, dy] of NEIGHBOR_OFFSETS) {
29	      const cell: Cell = [x + dx, y + dy];
30	      const key = toKey(cell);
31	      const previous = counts.get(key)?.count ?? 0;
32	      counts.set(key, { cell, count: previous + 1 });
33	    }
34	  }
35	  return counts;
36	}
